import{_ as t,o as a,c as d,a2 as s}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"A11y thresholds — SSOT","description":"","frontmatter":{},"headers":[],"relativePath":"quality/a11y-thresholds.md","filePath":"quality/a11y-thresholds.md"}'),i={name:"quality/a11y-thresholds.md"};function o(r,e,n,c,l,h){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="a11y-thresholds-—-ssot" tabindex="-1">A11y thresholds — SSOT <a class="header-anchor" href="#a11y-thresholds-—-ssot" aria-label="Permalink to &quot;A11y thresholds — SSOT&quot;">​</a></h1><h2 id="why-this-file-exists" tabindex="-1">Why this file exists <a class="header-anchor" href="#why-this-file-exists" aria-label="Permalink to &quot;Why this file exists&quot;">​</a></h2><p>kiwa v1.16 introduced <code>@kiwa/a11y</code> (axe-core WCAG 2.1 AA wrapper) as a single test-adapter package. v1.30 promotes accessibility from one-package coverage to a 37-package infra baseline mirroring the mutation-thresholds SSOT (<code>docs/quality/mutation-thresholds.md</code>, v1.27) and the perf-thresholds SSOT (<code>docs/quality/perf-thresholds.md</code>, v1.25). (The Issue AC calls it &quot;34 packages&quot; — the count is the 33 <code>@kiwa/*</code> packages published in v1.29 + <code>release-invariants</code>. This SSOT covers all 37 published packages including <code>perf-harness</code> + <code>quality-metrics</code> because they are the same publish set and share the same 4-tier rationale.)</p><p>Every kiwa package publishes an <code>.axe-config.mjs</code> that pins its WCAG 2.1 AA rule set + tag filter + <code>.a11y-baseline/{pkg}.json</code> output path, and every <code>test:a11y</code> script writes a machine-readable baseline that downstream release gates (v1.30-4, 13th axis) can enforce. Without a shared threshold rationale, each package would land its own bar and drift for the same reasons the mutation-testing rollout drifted before v1.27 — no documented &quot;why 0 critical here&quot; survives the review that lands the code six weeks later.</p><p>This doc pins every package to one of four rationale tiers. The tiers are named after the shape of the code axe-core runs over — pure logic, SSR / hydration wrapper, provider adapter, test harness — not the package name.</p><h2 id="tier-table" tabindex="-1">Tier table <a class="header-anchor" href="#tier-table" aria-label="Permalink to &quot;Tier table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>AA critical</th><th>AA serious</th><th>AA moderate</th><th>Applies to</th></tr></thead><tbody><tr><td>Core</td><td>0</td><td>0</td><td>0-3</td><td>Pure logic packages with no DOM output. Bar is 0 across the board because &quot;no DOM&quot; means &quot;no excuse&quot;. Moderate 0-3 covers axe incompleteness for headless test harnesses that still emit a jsdom fixture.</td></tr><tr><td>Framework</td><td>0</td><td>0-3</td><td>0-10</td><td>SSR / hydration / RSC / adapter-wrapper layers. Serious 0-3 is the tolerance for framework-owned markup (Next router link, Nuxt teleport, Astro island) whose fix requires an upstream PR.</td></tr><tr><td>Test type</td><td>0</td><td>0-3</td><td>0-10</td><td>Test harness packages (component / visual / a11y / e2e / ui) where DOM measurement noise + browser dependence produce false-positive violations that only reproduce inside our test runners. The bar is the same as Framework because the harness must not itself leak violations, but moderate 0-10 covers jsdom quirks.</td></tr><tr><td>SaaS</td><td>0</td><td>0</td><td>0</td><td>Provider-specific adapters (Stripe / Paddle / Anthropic / Ably / Redis / Prisma / …) that expose no DOM. Bar is a strict 0 because a SaaS adapter that emits any WCAG violation is emitting DOM it should not be emitting — the violation itself is a bug marker.</td></tr></tbody></table><p><code>AA critical</code>, <code>AA serious</code>, <code>AA moderate</code> map to axe-core&#39;s <code>impact</code> field on <code>AxeViolation</code> (see <code>packages/a11y/src/types.ts</code>). <code>minor</code> impact is not enforced; use it for team review only.</p><p>Kill line = <code>.a11y-baseline/{pkg}.json</code> reports one violation count per impact. <code>critical &gt; 0</code> fails the run in every tier. <code>serious</code> and <code>moderate</code> counts are checked against the tier&#39;s allowed range.</p><h2 id="tier-assignment-—-37-package-matrix" tabindex="-1">Tier assignment — 37-package matrix <a class="header-anchor" href="#tier-assignment-—-37-package-matrix" aria-label="Permalink to &quot;Tier assignment — 37-package matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Tier</th><th>Threshold (critical / serious / moderate)</th><th>Reason</th></tr></thead><tbody><tr><td><code>@kiwa/core</code></td><td>Core</td><td>0 / 0 / 0-3</td><td>Pure parser + pool logic every adapter depends on. No DOM.</td></tr><tr><td><code>@kiwa/api</code></td><td>Core</td><td>0 / 0 / 0-3</td><td>HTTP request client + MSW bridge. No DOM.</td></tr><tr><td><code>@kiwa/data</code></td><td>Core</td><td>0 / 0 / 0-3</td><td>Fixture builders + assertion helpers. No DOM.</td></tr><tr><td><code>@kiwa/cli-test</code></td><td>Core</td><td>0 / 0 / 0-3</td><td>CLI expectation runner. No DOM.</td></tr><tr><td><code>@kiwa/cli</code></td><td>Core</td><td>0 / 0 / 0-3</td><td>CLI runtime. No DOM.</td></tr><tr><td><code>@kiwa/observability</code></td><td>Core</td><td>0 / 0 / 0-3</td><td>Flaky detection + coverage gap analysis. No DOM.</td></tr><tr><td><code>@kiwa/perf-harness</code></td><td>Core</td><td>0 / 0 / 0-3</td><td>Perf runner + tinybench wrapper. No DOM.</td></tr><tr><td><code>@kiwa/quality-metrics</code></td><td>Core</td><td>0 / 0 / 0-3</td><td>Release gate calculator. No DOM.</td></tr><tr><td><code>@kiwa/release-invariants</code></td><td>Core</td><td>0 / 0 / 0-3</td><td>Release script filter + provenance flag + gate script checkers. No DOM.</td></tr><tr><td><code>@kiwa/nextjs</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>RSC + Server Actions + Middleware. Serious tolerance for Next router link internals.</td></tr><tr><td><code>@kiwa/nuxt</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>SSR + hydration + Nitro adapter. Serious tolerance for Nuxt teleport.</td></tr><tr><td><code>@kiwa/sveltekit</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>SSR + hydration + load / actions. Serious tolerance for SvelteKit-owned markup.</td></tr><tr><td><code>@kiwa/remix</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>SSR + loader / action + client hydration. Serious tolerance for Remix-owned markup.</td></tr><tr><td><code>@kiwa/astro</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>Islands + SSR + partial hydration. Serious tolerance for Astro island wrappers.</td></tr><tr><td><code>@kiwa/solidstart</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>Solid SSR + resource + server-function.</td></tr><tr><td><code>@kiwa/qwikcity</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>Resumability + SSR + route loader.</td></tr><tr><td><code>@kiwa/edge</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>Workers / Deno / Bun edge runtimes with divergent APIs.</td></tr><tr><td><code>@kiwa/solidjs</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>Solid signal + resource + SSR.</td></tr><tr><td><code>@kiwa/fresh</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>Deno Fresh islands + SSR.</td></tr><tr><td><code>@kiwa/hono</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>Hono edge + node adapter.</td></tr><tr><td><code>@kiwa/auth</code></td><td>Framework</td><td>0 / 0-3 / 0-10</td><td>NextAuth v5 / Lucia v3 / Better Auth / Clerk / Auth0 / Supabase Auth.</td></tr><tr><td><code>@kiwa/ai-llm</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>Anthropic / OpenAI / Vercel AI SDK / LangChain adapters. No DOM.</td></tr><tr><td><code>@kiwa/payment</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>Stripe / Paddle / Lemon Squeezy. No DOM.</td></tr><tr><td><code>@kiwa/queue</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>BullMQ / Inngest / Cloudflare Queues / SQS / RabbitMQ. No DOM.</td></tr><tr><td><code>@kiwa/cache</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>Redis / KeyDB / Memcached. No DOM.</td></tr><tr><td><code>@kiwa/streaming</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>Kafka / NATS / Redpanda. No DOM.</td></tr><tr><td><code>@kiwa/realtime</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>Supabase Realtime / Ably / Pusher / Socket.io. No DOM.</td></tr><tr><td><code>@kiwa/mcp</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>MCP JSON-RPC protocol + transport. No DOM.</td></tr><tr><td><code>@kiwa/agent</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>LangGraph + OpenAI Assistants v2. No DOM.</td></tr><tr><td><code>@kiwa/search</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>Algolia / Meilisearch / Typesense. No DOM.</td></tr><tr><td><code>@kiwa/orm</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>Prisma / Drizzle / Kysely. No DOM.</td></tr><tr><td><code>@kiwa/dapp</code></td><td>SaaS</td><td>0 / 0 / 0</td><td>viem + anvil + wallet fixture. No DOM.</td></tr><tr><td><code>@kiwa/ui</code></td><td>Test type</td><td>0 / 0-3 / 0-10</td><td>Vue / Solid / Lit / Qwik / Angular DOM harness. jsdom + framework noise.</td></tr><tr><td><code>@kiwa/a11y</code></td><td>Test type</td><td>0 / 0-3 / 0-10</td><td>axe-core WCAG 2.1 AA wrapper. Self-tests exercise DOM fixtures.</td></tr><tr><td><code>@kiwa/visual</code></td><td>Test type</td><td>0 / 0-3 / 0-10</td><td>Screenshot + baseline / diff / accept. DOM fixture noise.</td></tr><tr><td><code>@kiwa/component</code></td><td>Test type</td><td>0 / 0-3 / 0-10</td><td>Storybook + Playwright CT + Chromatic. DOM fixture noise.</td></tr><tr><td><code>@kiwa/e2e</code></td><td>Test type</td><td>0 / 0-3 / 0-10</td><td>Playwright fixture. Browser fixture noise.</td></tr></tbody></table><p>Any future adapter starts by picking the tier its code most resembles. If none fits, add a new tier here first, then the config.</p><h2 id="how-each-package-encodes-this" tabindex="-1">How each package encodes this <a class="header-anchor" href="#how-each-package-encodes-this" aria-label="Permalink to &quot;How each package encodes this&quot;">​</a></h2><p>Every <code>packages/*/.axe-config.mjs</code> starts with a header comment that names the tier and links back to this doc.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/**</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * A11y (axe-core) config for @kiwa/&lt;name&gt;.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * Tier: &lt;tier&gt; tier (critical 0 / serious &lt;range&gt; / moderate &lt;range&gt;) — &lt;one-line reason&gt;.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * SSOT: docs/quality/a11y-thresholds.md § &lt;tier&gt; tier.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> */</span></span></code></pre></div><p>The comment is the on-the-spot receipt. This doc is the shared law.</p><h2 id="config-shape" tabindex="-1">Config shape <a class="header-anchor" href="#config-shape" aria-label="Permalink to &quot;Config shape&quot;">​</a></h2><p><code>.axe-config.mjs</code> exports one default object with three top-level fields.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // WCAG 2.1 AA tag filter — axe-core scan will run only these rule tags.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  runOptions: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    runOnly: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;tag&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      values: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wcag2a&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wcag2aa&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wcag21a&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wcag21aa&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Impact threshold per this doc&#39;s tier table.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  thresholds: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    critical: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    serious: { max: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    moderate: { max: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Where the machine-readable baseline gets written.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  baselinePath: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;.a11y-baseline/&lt;pkg&gt;.json&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p><code>serious</code> / <code>moderate</code> accept <code>{ max: N }</code> (upper bound tolerated) or a raw number (strict equality — used by SaaS + Core <code>critical</code> / <code>serious</code>). <code>critical</code> is always a raw number and always <code>0</code> — enforced at the SSOT layer, never overridable.</p><h2 id="overrides" tabindex="-1">Overrides <a class="header-anchor" href="#overrides" aria-label="Permalink to &quot;Overrides&quot;">​</a></h2><p>A package may sit one tier stricter than its default (e.g. <code>@kiwa/component</code> sets <code>moderate.max = 0</code> if its Storybook fixtures reach zero violations). Stricter overrides do not need approval — they raise the floor. A looser override requires a one-line justification in the PR body of the change that introduces it, and must not raise <code>critical</code> above <code>0</code>. No override may ever raise the <code>critical</code> bar.</p><h2 id="baseline-snapshots" tabindex="-1">Baseline snapshots <a class="header-anchor" href="#baseline-snapshots" aria-label="Permalink to &quot;Baseline snapshots&quot;">​</a></h2><p>Each package writes a per-package baseline JSON to <code>.a11y-baseline/&lt;pkg&gt;.json</code>. The baseline records the last known green a11y report — a 3-layer harness envelope (v1.30-2, <code>docs/quality/a11y-thresholds.md § 3-layer harness</code>) recording violation counts per impact + surviving-violation list per layer + timestamp. <code>pnpm test:a11y</code> rewrites the baseline every run, and fails the run if the tier ceiling was breached (critical &gt; 0 in every tier, serious &gt; tier max, moderate &gt; tier max). Baseline refresh happens in-PR when violation counts drop, and is written by the same PR that improves the underlying markup — never as a standalone commit.</p><h2 id="_3-layer-harness-v1-30-2" tabindex="-1">3-layer harness (v1.30-2) <a class="header-anchor" href="#_3-layer-harness-v1-30-2" aria-label="Permalink to &quot;3-layer harness (v1.30-2)&quot;">​</a></h2><p>Every applicable package participates in three layers, each running axe-core once and recording its verdict separately in the baseline.</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it scans</th><th>Fixture shape</th></tr></thead><tbody><tr><td><code>jsdom</code></td><td>Static DOM audit — a jsdom Element / Document that the package produces without spinning up a browser. Fastest of the three, catches every non-runtime rule.</td><td><code>.axe-config.mjs &gt; fixtures.jsdom.context: Element | Document | string</code></td></tr><tr><td><code>playwright</code></td><td>Dynamic browser audit — axe-core inside a real Playwright page. Catches contrast + layout rules that jsdom&#39;s incomplete CSSOM cannot resolve.</td><td><code>.axe-config.mjs &gt; fixtures.playwright.results: AxeResults</code> (caller runs the Playwright evaluation, harness aggregates)</td></tr><tr><td><code>ssrHydration</code></td><td>SSR + hydration diff — axe-core over the SSR HTML string plus an optional post-hydration Element. Violations are unioned by rule id so SSR-only + hydration-only + shared violations each surface once.</td><td><code>.axe-config.mjs &gt; fixtures.ssrHydration.ssrHtml: string</code> (+ optional <code>hydrated: Element</code>)</td></tr></tbody></table><p>A package that intentionally does not participate in a layer omits the field, and the baseline records <code>applicable: false</code> with an explicit reason. Every current <code>@kiwa/*</code> core + framework adapter (v1.30-2 scope) is a test-adapter package that emits no runtime DOM, so its baseline records <code>layers-absent</code> — every layer is <code>applicable: false</code>, <code>totals</code> is zero, <code>ok</code> is <code>true</code>. The harness ran, proved the wiring is intact, and left the tier ceilings in force for the day a fixture is added.</p><p>The harness lives in <code>packages/a11y/src/layer-harness.ts</code> and is exported from <code>@kiwa/a11y</code> as <code>runLayerHarness</code>. Unit tests exhaust every branch — union dedupe, absent-layer reasons, tier breach detection, missing-document fallback — so the driver in <code>scripts/run-axe-baseline.mjs</code> stays thin.</p><h2 id="provider-provenance-v1-30-3" tabindex="-1">Provider provenance (v1.30-3) <a class="header-anchor" href="#provider-provenance-v1-30-3" aria-label="Permalink to &quot;Provider provenance (v1.30-3)&quot;">​</a></h2><p>SaaS-tier packages that wrap multiple provider SDKs (<code>auth</code> / <code>queue</code> / <code>cache</code> / <code>orm</code> / <code>payment</code> / <code>streaming</code>) declare an optional <code>providers</code> array on their <code>.axe-config.mjs</code>. The runner passes the list through to <code>.a11y-baseline/{pkg}.json</code> as a top-level <code>providers</code> field so downstream gates can prove the sweep considered every provider even when the baseline is layers-absent (no-DOM adapter has no violations to record but still needs provenance).</p><p>Each entry is an object with <code>name</code> required plus any of <code>protocol</code> / <code>semantics</code> / <code>backend</code> / <code>axis</code> optional strings — enough shape to record the AC&#39;s provider × axis matrices (<code>payment</code> = 3 × 9, <code>streaming</code> = 3 × 5, <code>orm</code> = 3 × 3 × 8, <code>auth</code> = 6 + 4 protocol).</p><table tabindex="0"><thead><tr><th>Package</th><th>Entry count</th><th>Shape</th></tr></thead><tbody><tr><td><code>@kiwa/auth</code></td><td>10</td><td>6 provider (auth0 / better-auth / clerk / lucia / supabase / supabase-advanced) + 4 protocol (oauth21 / oidc / passkey / webauthn).</td></tr><tr><td><code>@kiwa/queue</code></td><td>5</td><td>bullmq / inngest / cloudflare-queues / sqs / rabbitmq. <code>rabbitmq-advanced</code> is an axis of <code>rabbitmq</code>.</td></tr><tr><td><code>@kiwa/cache</code></td><td>3</td><td>in-memory / keydb / memcached.</td></tr><tr><td><code>@kiwa/payment</code></td><td>27</td><td>3 brand (stripe / paddle / lemonsqueezy) × 9 axis (invoice / retry / subscription-lifecycle / chargeback / dunning / tax / three-ds / sca / psd2).</td></tr><tr><td><code>@kiwa/streaming</code></td><td>15</td><td>3 brand (kafka / nats / redpanda) × 5 semantics (dlq / exactly-once / schema-registry / partition / retention).</td></tr><tr><td><code>@kiwa/orm</code></td><td>72</td><td>3 brand (drizzle / prisma / kysely) × 3 backend (postgres / mysql / sqlite) × 8 axis (cdc / replication / mvcc / partitioning / connection-pool / logical-replication / rls / vector-store).</td></tr></tbody></table><p>Non-SaaS packages omit the field; the baseline shape is unchanged (no <code>providers</code> key). Adding a new provider adapter is a two-file edit — append to <code>.axe-config.mjs</code> <code>providers</code> and re-run <code>pnpm test:a11y</code> to refresh the baseline — no other config changes needed.</p><h2 id="_13-axis-release-gate-integration-v1-30-4" tabindex="-1">13-axis release gate integration (v1.30-4) <a class="header-anchor" href="#_13-axis-release-gate-integration-v1-30-4" aria-label="Permalink to &quot;13-axis release gate integration (v1.30-4)&quot;">​</a></h2><p>v1.30-4 promotes the a11y violation count to a first-class 13th axis in the release gate (the 12th, mutation kill rate, was added in v1.27-4). <code>@kiwa/quality-metrics</code> will expose three symbols mirroring the mutation tier interface.</p><ul><li><code>DEFAULT_A11Y_TIER_THRESHOLDS</code> — the SSOT table (<code>core: {critical: 0, serious: 0, moderate: 3}</code>, <code>framework: {critical: 0, serious: 3, moderate: 10}</code>, <code>saas: {critical: 0, serious: 0, moderate: 0}</code>, <code>test-type: {critical: 0, serious: 3, moderate: 10}</code>), a <code>Readonly&lt;Record&lt;A11yTier, A11yThreshold&gt;&gt;</code>.</li><li><code>resolveA11yTier(label)</code> — normalises the verbal tier label (<code>Core</code> / <code>Framework</code> / <code>SaaS</code> / <code>Test type</code>) written in <code>.a11y-baseline/*.json</code> into the machine <code>A11yTier</code> enum. Case-insensitive, trim-tolerant.</li><li><code>assertA11yTier({ metric, tier, threshold? })</code> — asserts every impact count sits inside the tier&#39;s range. Empty-violation metrics do not throw (unlike mutation testing, an a11y run with zero violations is the desired state).</li></ul><p><code>evaluateReleaseGate</code> gains an optional third-parameter field <code>a11yTier</code> mirroring <code>mutationTier</code>. When <code>a11yTier</code> is omitted the verdict stays at 12 axes for backward compatibility. When present the verdict count grows by 1 (<code>axesEvaluated</code> becomes 13) and any threshold miss surfaces as an <code>a11y.tier</code> blocker.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><code>docs/quality/release-gate.md</code> — 12-axis release gate; v1.30-4 promotes it to 13.</li><li><code>docs/quality/mutation-thresholds.md</code> — mutation-testing 4-tier SSOT this file is patterned after.</li><li><code>docs/quality/perf-thresholds.md</code> — perf p95 SSOT (the original three-rationale model).</li><li><code>packages/a11y/src/audit.ts</code> — <code>runAxe</code> / <code>reportViolations</code> / <code>expectNoViolations</code>, the runtime primitives every <code>.axe-config.mjs</code> composes on top of.</li><li><code>packages/*/.axe-config.mjs</code> — per-package configs.</li><li><code>scripts/check-a11y-gates.mjs</code> — CI gate (added in v1.30-4).</li><li>root <code>package.json</code> <code>test:a11y</code> script — pnpm filter list covering all packages in this doc.</li></ul>`,40)])])}const u=t(i,[["render",o]]);export{k as __pageData,u as default};
